	private static void runAcknowledgedSpillRemainsUntilTheLastBranchCursorCloses(Path directory) throws Exception {
		PressureSettings oldSettings = pressureSettings();
		resetPressureState();
		Probe probe = new Probe(true);
		probe.spillAutoGrow = true;
		List<Statement> expected = statements("branch-reader", SMALL_EXPLICIT_ROWS);
		probe.expectedOverflowRows = expected;
		ProbeLmdbStore store = new ProbeLmdbStore(directory.toFile(), spillOwnershipMapConfig(), probe);
		SailRepository repository = new SailRepository(store);
		Set<Statement> traversed = new HashSet<>();
		int traversedCount = 0;
		Set<Statement> committed = Set.of();
		String committedNamespace = null;
		Set<Statement> reopenedRows = Set.of();
		String reopenedNamespace = null;
		Path spillPath = null;
		try {
			repository.init();
			probe.resetRuntimeCounts();
			SailSource branch = SeparateModelSnapshotSailStore.newBranch(
					store.getBackingStore().getExplicitSailSource(), probe::newModel);
			try (branch) {
				try (SailSink sink = branch.sink(IsolationLevels.SNAPSHOT_READ)) {
					for (Statement statement : expected) {
						sink.approve(statement);
					}
					sink.setNamespace(NAMESPACE_PREFIX, NAMESPACE_NAME);
					sink.flush();
				}
				List<TrackingOverflowModel> candidates = probe.modelsContainingAll(expected);
				assertEquals(1, candidates.size(), "the branch must retain one real overflow-capable changeset model");
				TrackingOverflowModel model = candidates.get(0);
				try (GcNotifications pressure = new GcNotifications()) {
					activatePressureAndAwait(pressure);
				}
				model.spillToDiskIfNeeded();
				assertTrue(model.isSpilled(), "the branch input must be migrated to a real disk-backed model");
				assertTrue(probe.spillTransactionStarts.get() > 0,
						"the adopted overflow store must run real native transactions");
				assertEquals(0, probe.spillFrozenReplayStarts.get(),
						"overflow migration must use its ordinary store policy");
				spillPath = probe.spillDirectory.get();
				assertNotNull(spillPath);
				assertTrue(Files.isDirectory(spillPath));

				System.out.println("CHILD_PHASE=ack-before-branch-dataset");
				SailDataset dataset = branch.dataset(IsolationLevels.SNAPSHOT_READ);
				System.out.println("CHILD_PHASE=ack-after-branch-dataset");
				try (dataset) {
					CloseableIteration<? extends Statement> cursor = dataset.getStatements(null, null, null);
					System.out.println("CHILD_PHASE=ack-after-cursor-open");
					try (cursor) {
						assertTrue(cursor.hasNext(), "the retained branch cursor must expose its spilled rows");
						traversed.add(cursor.next());
						traversedCount++;
						System.out.println("CHILD_PHASE=ack-after-first-row");
						System.out.println("CHILD_PHASE=ack-before-dataset-close");
						dataset.close();
						System.out.println("CHILD_PHASE=ack-after-dataset-close");
						System.out.println("CHILD_PHASE=ack-before-freeze");
						try (SailSource.FlushBatch batch = branch.freezeForFlush()) {
							System.out.println("CHILD_PHASE=ack-after-freeze");
							System.out.println("CHILD_PHASE=ack-before-batch-flush");
							batch.flush();
							System.out.println("CHILD_PHASE=ack-after-batch-flush");
							batch.unFreezeAndDiscardFlushed();
							System.out.println("CHILD_PHASE=ack-after-ack");
						}
						assertEquals(0, probe.spillStoreCloses.get(),
								"ACK must retain the spill store while the original dataset cursor is open");
						assertTrue(Files.isDirectory(spillPath), "the active cursor must retain its spill directory");
						System.out.println("CHILD_PHASE=ack-before-branch-close");
						branch.close();
						System.out.println("CHILD_PHASE=ack-after-branch-close");
						assertEquals(0, probe.spillStoreCloses.get(),
								"closing the branch must not dispose a spill store still owned by its cursor");
						assertTrue(Files.isDirectory(spillPath));
						while (cursor.hasNext()) {
							traversed.add(cursor.next());
							traversedCount++;
						}
					}
					assertEquals(1, probe.spillStoreCloses.get(),
							"the last cursor release must dispose the adopted spill store exactly once");
					assertFalse(Files.exists(spillPath),
							"the final cursor release must remove the owned spill directory");
				}
			}

			try (SailDataset reader = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.NONE)) {
				committed = Set.copyOf(readAllRows(reader));
				committedNamespace = reader.getNamespace(NAMESPACE_PREFIX);
			}
		} finally {
			closeCustomStoreAndRepository(store, repository);
			restorePressureSettings(oldSettings);
		}

		LmdbStore reopenedStore = new LmdbStore(directory.toFile(), spillOwnershipMapConfig());
		SailRepository reopened = new SailRepository(reopenedStore);
		try {
			reopened.init();
			try (RepositoryConnection reader = reopened.getConnection()) {
				reopenedRows = readAllRows(reader);
				reopenedNamespace = reader.getNamespace(NAMESPACE_PREFIX);
			}
		} finally {
			reopened.shutDown();
		}
		int observedTraversedCount = traversedCount;
		Set<Statement> observedTraversed = Set.copyOf(traversed);
		Set<Statement> observedCommitted = committed;
		String observedCommittedNamespace = committedNamespace;
		Set<Statement> observedReopenedRows = reopenedRows;
		String observedReopenedNamespace = reopenedNamespace;
		assertAll("a confirmed branch ACK preserves an existing cursor's spill ownership",
				() -> assertEquals(expected.size(), observedTraversedCount,
						"the cursor must finish the original complete row set"),
				() -> assertEquals(Set.copyOf(expected), observedTraversed,
						"the cursor must return each original statement"),
				() -> assertEquals(Set.copyOf(expected), observedCommitted,
						"ACK must publish every row to the main store"),
				() -> assertEquals(NAMESPACE_NAME, observedCommittedNamespace),
				() -> assertEquals(Set.copyOf(expected), observedReopenedRows,
						"the acknowledged rows must survive reopening"),
				() -> assertEquals(NAMESPACE_NAME, observedReopenedNamespace));
	}

